import{_ as a,o as s,c as n,a3 as d}from"./chunks/framework.bvEHUNtb.js";const b=JSON.parse('{"title":"断占总诀篇之三：观物占","description":"以卦象观察器物的形、色、数与成败，深化以象断物的训练。","frontmatter":{"title":"断占总诀篇之三：观物占","description":"以卦象观察器物的形、色、数与成败，深化以象断物的训练。","category":"学习计划 · 第三阶段"},"headers":[],"relativePath":"yijing/meihua-yishu/duan-zhan-zong-jue/observing-things-divination.md","filePath":"yijing/meihua-yishu/duan-zhan-zong-jue/observing-things-divination.md","lastUpdated":1786982540000}'),p={name:"yijing/meihua-yishu/duan-zhan-zong-jue/observing-things-divination.md"};function e(l,t,i,r,o,h){return s(),n("div",null,[...t[0]||(t[0]=[d(`<h1 id="【断占总诀篇之三】诸卦反对性情·占物类例·物数为体诀·观物诸诀·万物戏验" tabindex="-1">【断占总诀篇之三】诸卦反对性情·占物类例·物数为体诀·观物诸诀·万物戏验 <a class="header-anchor" href="#【断占总诀篇之三】诸卦反对性情·占物类例·物数为体诀·观物诸诀·万物戏验" aria-label="Permalink to &quot;【断占总诀篇之三】诸卦反对性情·占物类例·物数为体诀·观物诸诀·万物戏验&quot;">​</a></h1><blockquote><p>本篇专论「观物占」——通过卦象断定手中或笼中之物的性质、形色、数目、成败。是梅花易数「以象断物」最完整的专论。</p></blockquote><hr><h2 id="📜-原文" tabindex="-1">📜 原文 <a class="header-anchor" href="#📜-原文" aria-label="Permalink to &quot;📜 原文&quot;">​</a></h2><h3 id="诸卦反对性情" tabindex="-1">诸卦反对性情 <a class="header-anchor" href="#诸卦反对性情" aria-label="Permalink to &quot;诸卦反对性情&quot;">​</a></h3><p>干刚坤柔反其义，比卦欢欣困忧虑。<br> 临逢百物观求之，蒙卦难明屯不失。<br> 大畜其卦福之生，无妄若遇祸之始。<br> 升者去而不复回，萃者聚而终不去。<br> 谦卦自尊豫怠人，震则动而艮则止。<br> 兑主外遇祸之藏，随前坎后偷安矣。<br> 剥体消烂复自生，蛊改前非而已矣。<br> 明夷内朗又逢伤，晋主外明并通理。<br> 益拟茂盛损象衰，咸速恒迟涣远遁。<br> 同人内亲睽外疏，解卦从容蹇难启。<br> 离文美丽艮光明，遁退回身姤相遇。<br> 大有曰众丰曰多，坎卦履险震卦起。<br> 需不进兮讼不宁，既济一定无后虑。<br> 未济之卦男之终，归妹之辞归之始。<br> 否遭大往而小来，泰卦大来而小去。<br> 革去旧故鼎从新，小畜曰寡噬嗑食。<br> 旅羁其外大过颠，夬卦分明曰快利。<br> 要将字字考精详，杂卦性情反对是。</p><h3 id="占物类例" tabindex="-1">占物类例 <a class="header-anchor" href="#占物类例" aria-label="Permalink to &quot;占物类例&quot;">​</a></h3><p>凡看物数，看其成卦，观其爻辞。如得干，曰「潜龙勿用」，乃曰不可用之物；「见龙在田」，乃曰田中之物；「或跃在渊」，乃曰水中之物；「亢龙有悔」，乃废物也。如得坤之「直、方、大」，乃曰直而方大之器物；「括囊无咎」，乃曰包裹之物；「黄裳元吉」，乃曰黄色衣服之物；「其血玄黄」，乃石物或逢石而破；「困于株林」，乃曰木物。又言爻辞，不言物类，而不能决者，须以八卦所属之象察之。</p><p>又诀，体用断物之妙，生克制化之妙，于诸诀中此极为美验。其所以生体者，为可食之物；克体者，为可近人之秽物。体生者，为不成之器；体克者，为破碎损折之物；比和者，乃有用成器之物，又生体象者为贵物，克体象者为贱物，所泄为废物也。</p><p>又诀，凡算此数，以体卦为主，看其刚柔。用卦看其有用无用。体生方圆曲直，可作可用，如用生体，乃可食。用变互卦，看其色与数目。此互卦决其物之数目也。如互见干、兑，决为一二之数。互见艮、坤，为七八之数也。但互卦重干、重艮、重坤、重坎、重离之属，皆是两件。物乘旺，物数多，衰而物少。离为中虚之物，或空手无物。又决物之数者，如互艮卦，先天七数，后天亦不出八数之外。</p><h3 id="物数为体诀" tabindex="-1">物数为体诀 <a class="header-anchor" href="#物数为体诀" aria-label="Permalink to &quot;物数为体诀&quot;">​</a></h3><p>凡算物数者，不但以体卦为体，凡卦之多者，皆可为体。如干金多，以金为体，则多刚；坤多以土为体，多柔。干卦体卦干而互又是干。固曰：金为体而刚矣，便是圆健刚硬之物。非金非石，此为体矣。观物有体互变卦，并无生旺之气者，为不入五行物。观物观爻，如八卦中阳爻多，乃多刚之物；阴爻多，乃多柔之物。</p><p>又诀，观物变在五六爻，多是能飞动之物。</p><h3 id="观物看变爻为主" tabindex="-1">观物看变爻为主 <a class="header-anchor" href="#观物看变爻为主" aria-label="Permalink to &quot;观物看变爻为主&quot;">​</a></h3><p>凡观物，以变卦为主，应用之应验也。如得干，初爻变为巽，金刀削过之木物。二爻动，变为离，乃火中锻炼之金。三爻动，变为兑，乃毁折五金之器，虽圆而破处多也。</p><h3 id="观物克应法" tabindex="-1">观物克应法 <a class="header-anchor" href="#观物克应法" aria-label="Permalink to &quot;观物克应法&quot;">​</a></h3><p>凡算物之成败，又看体卦克应如何。成卦未决之际，有见圆物相遇，即断圆物。见有负土者过，即断为土中之物。见刚健之物，即言是刚健之物。见有柔腐之物，即言是柔腐之物。</p><h3 id="观物趣时诀" tabindex="-1">观物趣时诀 <a class="header-anchor" href="#观物趣时诀" aria-label="Permalink to &quot;观物趣时诀&quot;">​</a></h3><p>凡算物，趣时察理，无有不验。以春得震、离为花，夏得震为有声之物，秋得兑为毁折成器之物，冬得坤为无用土物也。</p><h3 id="观物用易例" tabindex="-1">观物用易例 <a class="header-anchor" href="#观物用易例" aria-label="Permalink to &quot;观物用易例&quot;">​</a></h3><p>有人以笼盛物者，算得地天泰之初变升，互见震、兑，曰此必是草木类而生土中也。色青根黄，当连根之草木也。盖爻辞曰：「拔茅茹，以其汇。」乃曰：此乃干根之草木也，视之乃草木连根，新采于土中也。互震为清色，兑为黄根也。</p><p>又有以锺覆物者，令占之，得火风鼎之雷风恒。乃曰：此有声价气势之物，虽圆而今毁缺矣。其色白而可用。盖其辞曰：「鼎玉铉，大吉。」互见干、兑，虽圆而毁也。开视之，乃玉绦环，果破矣。</p><h3 id="万物戏验" tabindex="-1">万物戏验 <a class="header-anchor" href="#万物戏验" aria-label="Permalink to &quot;万物戏验&quot;">​</a></h3><p>凡猜手中物，干金为圆白之物。其色白，其性刚，为宝货之物，有气为无价物。坎为黑色，性柔，近水之物。又艮为土中之物，瓦石之类，有气为成器之物，其色黄。逢兑克，无气，折伤之物。又巽、震为竹木，有气为有用之物，为可食之物；无气为竹木之属。遇兑之属可食，当时之果物，色青。有气柔，无气刚。震、巽遇坎为污湿物，或有气；如无气，为烂朽之木。离色亦，性柔，有水有木，而火焚之，必炭之类。有气，为价值可货之物。坤为土中之物，色黄而性温。兑为毁折之物，带口。凡占物，以春震巽、夏离、秋干兑、冬坎皆当以为可用之物，成器之物。否则为无用之物。值六虚冲破，则必无物而空手矣。</p><hr><h2 id="🔤-注音与字词" tabindex="-1">🔤 注音与字词 <a class="header-anchor" href="#🔤-注音与字词" aria-label="Permalink to &quot;🔤 注音与字词&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字词</th><th>注音</th><th>释义</th></tr></thead><tbody><tr><td>反对</td><td>—</td><td>易学术语，指卦象颠倒（上下互换）或错卦（阴阳互换）</td></tr><tr><td>比卦</td><td>bǐ</td><td>水地比，亲比·欢欣之象</td></tr><tr><td>困卦</td><td>—</td><td>泽水困，困厄·忧虑之象</td></tr><tr><td>蒙卦</td><td>méng</td><td>山水蒙，蒙昧·难明之象</td></tr><tr><td>屯卦</td><td>zhūn</td><td>水雷屯，艰难但不失，屯：难也</td></tr><tr><td>大畜</td><td>—</td><td>山天大畜，积蓄·福之生</td></tr><tr><td>无妄</td><td>—</td><td>天雷无妄，无故之灾，祸之始</td></tr><tr><td>萃卦</td><td>cuì</td><td>泽地萃，聚集·不散</td></tr><tr><td>豫卦</td><td>yù</td><td>雷地豫，怠惰·安逸</td></tr><tr><td>明夷</td><td>míng yí</td><td>地火明夷，内明外伤，夷：伤也</td></tr><tr><td>晋卦</td><td>jìn</td><td>火地晋，外明·进也</td></tr><tr><td>涣卦</td><td>huàn</td><td>风水涣，涣散·远</td></tr><tr><td>遁卦</td><td>dùn</td><td>天山遁，退避·远遁</td></tr><tr><td>睽卦</td><td>kuí</td><td>火泽睽，乖离·外疏</td></tr><tr><td>蹇卦</td><td>jiǎn</td><td>水山蹇，艰难·难以启动</td></tr><tr><td>姤卦</td><td>gòu</td><td>天风姤，相遇·邂逅</td></tr><tr><td>夬卦</td><td>guài</td><td>泽天夬，决断·快利</td></tr><tr><td>噬嗑</td><td>shì hé</td><td>火雷噬嗑，噬：咬，嗑：合，主饮食·刑狱</td></tr><tr><td>括囊</td><td>kuò náng</td><td>扎紧袋口，包裹之物</td></tr><tr><td>黄裳</td><td>huáng cháng</td><td>黄色下裳（裙），元吉</td></tr><tr><td>株林</td><td>zhū lín</td><td>树木丛林，困于株林：困于木物</td></tr><tr><td>趣时</td><td>qù shí</td><td>顺应时令，趣：趋向</td></tr><tr><td>锺覆</td><td>zhōng fù</td><td>用钟（器皿）覆盖，令人猜测其中之物</td></tr><tr><td>玉绦环</td><td>tāo</td><td>绦：丝带，玉绦环：穿有丝带的玉环</td></tr><tr><td>六虚冲破</td><td>—</td><td>六爻皆动或冲克，卦象空虚，主无物</td></tr><tr><td>五金</td><td>—</td><td>金·银·铜·铁·锡，泛指金属器物</td></tr></tbody></table><hr><h2 id="📖-白话译文" tabindex="-1">📖 白话译文 <a class="header-anchor" href="#📖-白话译文" aria-label="Permalink to &quot;📖 白话译文&quot;">​</a></h2><h3 id="诸卦反对性情-逐句译" tabindex="-1">诸卦反对性情（逐句译） <a class="header-anchor" href="#诸卦反对性情-逐句译" aria-label="Permalink to &quot;诸卦反对性情（逐句译）&quot;">​</a></h3><p>此歌取自《杂卦传》，以对比方式说明六十四卦的性情：</p><table tabindex="0"><thead><tr><th>原文</th><th>卦名</th><th>性情</th></tr></thead><tbody><tr><td>干刚坤柔反其义</td><td>乾·坤</td><td>乾刚健，坤柔顺，两者相反相成</td></tr><tr><td>比卦欢欣困忧虑</td><td>比·困</td><td>比：亲比欢欣；困：困厄忧虑</td></tr><tr><td>临逢百物观求之</td><td>临·观</td><td>临：临近百物，有所求；观：观察审视</td></tr><tr><td>蒙卦难明屯不失</td><td>蒙·屯</td><td>蒙：蒙昧难明；屯：艰难但不失</td></tr><tr><td>大畜其卦福之生</td><td>大畜·无妄</td><td>大畜：积蓄生福；无妄：无故遇祸</td></tr><tr><td>升者去而不复回</td><td>升·萃</td><td>升：上升离去不回；萃：聚集不散</td></tr><tr><td>谦卦自尊豫怠人</td><td>谦·豫</td><td>谦：谦而自尊；豫：安逸怠惰</td></tr><tr><td>震则动而艮则止</td><td>震·艮</td><td>震：动；艮：止</td></tr><tr><td>兑主外遇祸之藏</td><td>兑·巽</td><td>兑：外遇有祸但内藏；巽：随顺</td></tr><tr><td>随前坎后偷安矣</td><td>随·蛊</td><td>随：随顺在前；坎：险在后，偷安</td></tr><tr><td>剥体消烂复自生</td><td>剥·复</td><td>剥：剥落消烂；复：自然复生</td></tr><tr><td>蛊改前非而已矣</td><td>蛊</td><td>蛊：改正前非</td></tr><tr><td>明夷内朗又逢伤</td><td>明夷·晋</td><td>明夷：内明外伤；晋：外明通达</td></tr><tr><td>益拟茂盛损象衰</td><td>益·损</td><td>益：茂盛增益；损：衰减</td></tr><tr><td>咸速恒迟涣远遁</td><td>咸·恒·涣·遁</td><td>咸：感应迅速；恒：持久而迟；涣：涣散远去；遁：退避</td></tr><tr><td>同人内亲睽外疏</td><td>同人·睽</td><td>同人：内部亲近；睽：外部疏离</td></tr><tr><td>解卦从容蹇难启</td><td>解·蹇</td><td>解：从容解脱；蹇：艰难难以启动</td></tr><tr><td>离文美丽艮光明</td><td>离·艮</td><td>离：文采美丽；艮：光明笃实</td></tr><tr><td>遁退回身姤相遇</td><td>遁·姤</td><td>遁：退避回身；姤：邂逅相遇</td></tr><tr><td>大有曰众丰曰多</td><td>大有·丰</td><td>大有：众多；丰：丰盛</td></tr><tr><td>坎卦履险震卦起</td><td>坎·震</td><td>坎：履险；震：奋起</td></tr><tr><td>需不进兮讼不宁</td><td>需·讼</td><td>需：等待不进；讼：争讼不宁</td></tr><tr><td>既济一定无后虑</td><td>既济·未济</td><td>既济：已成定局无后顾；未济：男之终（未竟之事）</td></tr><tr><td>归妹之辞归之始</td><td>归妹</td><td>归妹：归嫁之始</td></tr><tr><td>否遭大往而小来</td><td>否·泰</td><td>否：大往小来（阴盛阳衰）；泰：大来小去（阳盛）</td></tr><tr><td>革去旧故鼎从新</td><td>革·鼎</td><td>革：去旧；鼎：从新</td></tr><tr><td>小畜曰寡噬嗑食</td><td>小畜·噬嗑</td><td>小畜：积蓄少；噬嗑：饮食·刑狱</td></tr><tr><td>旅羁其外大过颠</td><td>旅·大过</td><td>旅：羁旅在外；大过：颠覆过度</td></tr><tr><td>夬卦分明曰快利</td><td>夬</td><td>夬：决断快利</td></tr></tbody></table><h3 id="占物类例-译" tabindex="-1">占物类例（译） <a class="header-anchor" href="#占物类例-译" aria-label="Permalink to &quot;占物类例（译）&quot;">​</a></h3><p><strong>第一法：爻辞取象</strong></p><p>看所得之卦的爻辞，直接从爻辞文字中取物象：</p><table tabindex="0"><thead><tr><th>卦爻</th><th>爻辞</th><th>断物</th></tr></thead><tbody><tr><td>乾初爻</td><td>潜龙勿用</td><td>不可用之物</td></tr><tr><td>乾二爻</td><td>见龙在田</td><td>田中之物</td></tr><tr><td>乾四爻</td><td>或跃在渊</td><td>水中之物</td></tr><tr><td>乾上爻</td><td>亢龙有悔</td><td>废物</td></tr><tr><td>坤二爻</td><td>直·方·大</td><td>直而方大之器物</td></tr><tr><td>坤四爻</td><td>括囊无咎</td><td>包裹之物</td></tr><tr><td>坤五爻</td><td>黄裳元吉</td><td>黄色衣服之物</td></tr><tr><td>坤上爻</td><td>其血玄黄</td><td>石物或逢石而破</td></tr><tr><td>坤（困卦）</td><td>困于株林</td><td>木物</td></tr></tbody></table><p>爻辞不能决断时，退而用八卦所属之象察之。</p><p><strong>第二法：体用生克断物性</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>生体之卦 → 可食之物（滋养体者）</span></span>
<span class="line"><span>克体之卦 → 可近人之秽物（伤体者）</span></span>
<span class="line"><span>体生用   → 不成之器（体气外泄，物未成）</span></span>
<span class="line"><span>体克用   → 破碎损折之物（体强克外，物受损）</span></span>
<span class="line"><span>比和     → 有用成器之物（和谐，物完整有用）</span></span>
<span class="line"><span>生体象   → 贵物</span></span>
<span class="line"><span>克体象   → 贱物</span></span>
<span class="line"><span>体所泄   → 废物</span></span></code></pre></div><p><strong>第三法：互卦断物之数目与颜色</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>互见乾·兑 → 一·二之数</span></span>
<span class="line"><span>互见艮·坤 → 七·八之数</span></span>
<span class="line"><span>互卦重复（重乾·重艮等）→ 两件</span></span>
<span class="line"><span>物乘旺 → 物数多；物衰 → 物数少</span></span>
<span class="line"><span>离为中虚之物，或空手无物</span></span></code></pre></div><h3 id="物数为体诀-译" tabindex="-1">物数为体诀（译） <a class="header-anchor" href="#物数为体诀-译" aria-label="Permalink to &quot;物数为体诀（译）&quot;">​</a></h3><p>断物不只以体卦为体，<strong>卦中出现最多的五行，皆可为体</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>乾金多 → 以金为体 → 多刚</span></span>
<span class="line"><span>坤土多 → 以土为体 → 多柔</span></span>
<span class="line"><span>体卦乾 + 互卦又乾 → 金体极刚 → 圆健刚硬之物</span></span></code></pre></div><p><strong>阴阳爻断刚柔</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阳爻多 → 多刚之物</span></span>
<span class="line"><span>阴爻多 → 多柔之物</span></span></code></pre></div><p><strong>特殊规则</strong>：</p><ul><li>体·互·变卦皆无生旺之气 → 不入五行之物（难以归类）</li><li>变爻在五·六爻 → 多是能飞动之物（鸟·虫·飞禽）</li></ul><h3 id="观物看变爻为主-译" tabindex="-1">观物看变爻为主（译） <a class="header-anchor" href="#观物看变爻为主-译" aria-label="Permalink to &quot;观物看变爻为主（译）&quot;">​</a></h3><p>观物以变卦为主，变爻位置决定物的性质：</p><p>以乾卦为例：</p><table tabindex="0"><thead><tr><th>动爻</th><th>变卦</th><th>断物</th></tr></thead><tbody><tr><td>初爻动</td><td>变巽</td><td>金刀削过之木物（乾金·巽木，金加工木）</td></tr><tr><td>二爻动</td><td>变离</td><td>火中锻炼之金（乾金经离火锻炼）</td></tr><tr><td>三爻动</td><td>变兑</td><td>毁折五金之器，虽圆而破处多（兑为毁折）</td></tr></tbody></table><h3 id="观物克应法-译" tabindex="-1">观物克应法（译） <a class="header-anchor" href="#观物克应法-译" aria-label="Permalink to &quot;观物克应法（译）&quot;">​</a></h3><p>成卦未决之际，以当下所见的外应印证物象：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>见圆物 → 断圆物</span></span>
<span class="line"><span>见负土者过 → 断土中之物</span></span>
<span class="line"><span>见刚健之物 → 断刚健之物</span></span>
<span class="line"><span>见柔腐之物 → 断柔腐之物</span></span></code></pre></div><h3 id="观物趣时诀-译" tabindex="-1">观物趣时诀（译） <a class="header-anchor" href="#观物趣时诀-译" aria-label="Permalink to &quot;观物趣时诀（译）&quot;">​</a></h3><p>顺应时令取象，无有不验：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>春得震·离 → 花（春花，震为生发，离为文采）</span></span>
<span class="line"><span>夏得震   → 有声之物（震为雷声，夏季震动）</span></span>
<span class="line"><span>秋得兑   → 毁折成器之物（兑为收割·成器）</span></span>
<span class="line"><span>冬得坤   → 无用土物（冬藏，坤土闭藏）</span></span></code></pre></div><h3 id="观物用易例-案例译" tabindex="-1">观物用易例（案例译） <a class="header-anchor" href="#观物用易例-案例译" aria-label="Permalink to &quot;观物用易例（案例译）&quot;">​</a></h3><p><strong>案例一：笼中之物</strong></p><p>卦：地天泰，初爻动，变地泽升，互见震·兑</p><p>断：</p><ul><li>泰卦初爻辞「拔茅茹，以其汇」→ 连根之草木</li><li>互震 → 青色（木色）</li><li>互兑 → 黄根（兑为金黄）</li><li>坤土（下卦变后仍有坤象）→ 生于土中</li></ul><p>结论：<strong>连根带土的草木，色青根黄，新采于土中。</strong></p><p>开笼验之：果然是连根新采的草木。✅</p><p><strong>案例二：钟覆之物</strong></p><p>卦：火风鼎，变雷风恒，互见乾·兑</p><p>断：</p><ul><li>鼎卦上爻辞「鼎玉铉，大吉」→ 玉质之物</li><li>互见乾·兑 → 虽圆而毁（乾圆·兑毁折）</li><li>恒卦 → 有声价气势之物</li><li>色白（乾兑皆白）</li></ul><p>结论：<strong>有声价的玉质圆形之物，但已破损。</strong></p><p>开钟验之：果然是玉绦环，且已破裂。✅</p><h3 id="万物戏验-各卦手中物速断表" tabindex="-1">万物戏验（各卦手中物速断表） <a class="header-anchor" href="#万物戏验-各卦手中物速断表" aria-label="Permalink to &quot;万物戏验（各卦手中物速断表）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>卦</th><th>颜色</th><th>性质</th><th>有气（旺）</th><th>无气（衰）</th><th>特殊情况</th></tr></thead><tbody><tr><td>乾</td><td>白</td><td>刚·圆</td><td>无价宝货</td><td>普通金属</td><td>—</td></tr><tr><td>坎</td><td>黑</td><td>柔</td><td>近水之物</td><td>—</td><td>—</td></tr><tr><td>艮</td><td>黄</td><td>土·瓦石</td><td>成器之物</td><td>折伤之物（逢兑）</td><td>—</td></tr><tr><td>震·巽</td><td>青</td><td>竹木</td><td>可食之物</td><td>竹木之属</td><td>遇坎→污湿物或烂朽木</td></tr><tr><td>离</td><td>赤</td><td>柔·燥</td><td>价值可货之物</td><td>炭类</td><td>有水有木而火焚→炭</td></tr><tr><td>坤</td><td>黄</td><td>温·土</td><td>土中之物</td><td>—</td><td>—</td></tr><tr><td>兑</td><td>白</td><td>毁折·带口</td><td>—</td><td>破损之物</td><td>—</td></tr></tbody></table><p><strong>时令加持</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>春：震·巽当令 → 可用成器之物</span></span>
<span class="line"><span>夏：离当令   → 可用成器之物</span></span>
<span class="line"><span>秋：乾·兑当令 → 可用成器之物</span></span>
<span class="line"><span>冬：坎当令   → 可用成器之物</span></span>
<span class="line"><span>非当令之卦   → 无用之物</span></span>
<span class="line"><span>值六虚冲破   → 必无物，空手</span></span></code></pre></div><hr><h2 id="🧭-义理解析" tabindex="-1">🧭 义理解析 <a class="header-anchor" href="#🧭-义理解析" aria-label="Permalink to &quot;🧭 义理解析&quot;">​</a></h2><h3 id="一、诸卦反对性情-六十四卦的「性格」" tabindex="-1">一、诸卦反对性情：六十四卦的「性格」 <a class="header-anchor" href="#一、诸卦反对性情-六十四卦的「性格」" aria-label="Permalink to &quot;一、诸卦反对性情：六十四卦的「性格」&quot;">​</a></h3><p>此歌出自《周易·杂卦传》，是孔子对六十四卦性情的精炼总结。梅花易数引用此歌，目的是：<strong>断卦时，卦名本身就是一个象</strong>。</p><p>几个最重要的对比：</p><p><strong>剥·复</strong>：「剥体消烂复自生」</p><ul><li>剥（山地剥）：剥落·消烂，阴盛阳衰到极点</li><li>复（地雷复）：一阳来复，自然复生</li><li>这是易理中「物极必反」最典型的一对</li></ul><p><strong>升·萃</strong>：「升者去而不复回，萃者聚而终不去」</p><ul><li>升（地风升）→ 行人占：去而不回（❓-026 在此解答）</li><li>萃（泽地萃）→ 聚集不散，事物凝聚</li></ul><p><strong>咸·恒</strong>：「咸速恒迟」</p><ul><li>咸（泽山咸）：感应迅速，少男少女之卦，感而遂通</li><li>恒（雷风恒）：持久而迟，长男长女之卦，恒久不变</li></ul><p><strong>同人·睽</strong>：「同人内亲睽外疏」</p><ul><li>同人（天火同人）：内部亲和</li><li>睽（火泽睽）：外部乖离疏远</li></ul><h3 id="二、占物三法-爻辞·体用·互卦-层层递进" tabindex="-1">二、占物三法：爻辞·体用·互卦，层层递进 <a class="header-anchor" href="#二、占物三法-爻辞·体用·互卦-层层递进" aria-label="Permalink to &quot;二、占物三法：爻辞·体用·互卦，层层递进&quot;">​</a></h3><p>本篇给出了断物的三个层次，优先级依次递进：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一层：爻辞取象（最直接）</span></span>
<span class="line"><span>↓ 爻辞不能决断时</span></span>
<span class="line"><span>第二层：体用生克断物性（定性）</span></span>
<span class="line"><span>↓ 需要进一步细化时</span></span>
<span class="line"><span>第三层：互卦断颜色与数目（定量）</span></span></code></pre></div><p>这三层是一个完整的断物框架：</p><ul><li>爻辞告诉你「这个物是什么」</li><li>体用生克告诉你「这个物是好是坏·是贵是贱」</li><li>互卦告诉你「这个物有几件·是什么颜色」</li></ul><h3 id="三、体用生克断物性-最精妙的对应" tabindex="-1">三、体用生克断物性：最精妙的对应 <a class="header-anchor" href="#三、体用生克断物性-最精妙的对应" aria-label="Permalink to &quot;三、体用生克断物性：最精妙的对应&quot;">​</a></h3><p>这一段是全书「观物占」最精华的部分：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>生体 → 可食之物</span></span></code></pre></div><p>生体 = 滋养我的，食物滋养人，逻辑完全对应。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>克体 → 可近人之秽物</span></span></code></pre></div><p>克体 = 伤害我的，秽物（垃圾·污物）靠近人但有害，逻辑对应。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>体生 → 不成之器</span></span></code></pre></div><p>体生用 = 体的气外泄，物的能量散出去了，所以「不成之器」——还没做完的东西。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>体克 → 破碎损折之物</span></span></code></pre></div><p>体克用 = 体强力克外，物受到强力作用，所以是破损之物。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>比和 → 有用成器之物</span></span></code></pre></div><p>比和 = 和谐平衡，物完整有用，是最理想的状态。</p><p>这五个对应，把体用生克的逻辑完美地映射到物的性质上，是梅花易数「以象断物」最精妙的理论。</p><h3 id="四、变爻为主-物的「加工痕迹」" tabindex="-1">四、变爻为主：物的「加工痕迹」 <a class="header-anchor" href="#四、变爻为主-物的「加工痕迹」" aria-label="Permalink to &quot;四、变爻为主：物的「加工痕迹」&quot;">​</a></h3><p>「观物看变爻为主」这一节，揭示了一个重要的逻辑：</p><blockquote><p><strong>变爻 = 物经历过的「变化·加工」</strong></p></blockquote><p>以乾卦为例：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>乾（金）初爻变巽（木）→ 金刀削过的木物</span></span>
<span class="line"><span>（金加工了木，留下了金的痕迹）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>乾（金）二爻变离（火）→ 火中锻炼的金</span></span>
<span class="line"><span>（金经过火的锻炼，是精炼金属）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>乾（金）三爻变兑（毁折）→ 破损的金属器</span></span>
<span class="line"><span>（金遇毁折，是破损之物）</span></span></code></pre></div><p>变爻不只是「结局」，在观物占中，它更像是「这个物的来历和状态」。</p><h3 id="五、趣时诀-时令是象的背景色" tabindex="-1">五、趣时诀：时令是象的背景色 <a class="header-anchor" href="#五、趣时诀-时令是象的背景色" aria-label="Permalink to &quot;五、趣时诀：时令是象的背景色&quot;">​</a></h3><p>「趣时察理，无有不验」——时令是所有象的背景色，同一个卦在不同时令下，象意完全不同：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>春得震·离 → 花（生发·文采，春天的花）</span></span>
<span class="line"><span>夏得震   → 有声之物（震为雷，夏雷最盛）</span></span>
<span class="line"><span>秋得兑   → 成器之物（秋收·收割·成器）</span></span>
<span class="line"><span>冬得坤   → 无用土物（冬藏，土物闭藏无用）</span></span></code></pre></div><p>这与体用衰旺之诀完全呼应：当令之卦，物有用；非当令之卦，物无用。</p><hr><h2 id="🔍-案例复盘" tabindex="-1">🔍 案例复盘 <a class="header-anchor" href="#🔍-案例复盘" aria-label="Permalink to &quot;🔍 案例复盘&quot;">​</a></h2><h3 id="案例一-地天泰初爻动" tabindex="-1">案例一：地天泰初爻动 <a class="header-anchor" href="#案例一-地天泰初爻动" aria-label="Permalink to &quot;案例一：地天泰初爻动&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>本卦：地天泰（坤上乾下）</span></span>
<span class="line"><span>初爻动（乾初爻）→ 变地泽临（坤上兑下）</span></span>
<span class="line"><span>互卦：震（下互二三四爻）·兑（上互三四五爻）</span></span></code></pre></div><p>断物逻辑：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 爻辞：泰卦初爻「拔茅茹，以其汇」</span></span>
<span class="line"><span>   → 茅草连根拔起，汇聚成束</span></span>
<span class="line"><span>   → 断：连根之草木</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 互震（木·青色）→ 物色青</span></span>
<span class="line"><span>3. 互兑（金黄）→ 根色黄</span></span>
<span class="line"><span>4. 坤（土）→ 生于土中，新采</span></span>
<span class="line"><span></span></span>
<span class="line"><span>综合：连根带土的草木，色青根黄</span></span></code></pre></div><p>验证：笼中果然是连根新采的草木 ✅</p><h3 id="案例二-火风鼎变雷风恒" tabindex="-1">案例二：火风鼎变雷风恒 <a class="header-anchor" href="#案例二-火风鼎变雷风恒" aria-label="Permalink to &quot;案例二：火风鼎变雷风恒&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>本卦：火风鼎（离上巽下）</span></span>
<span class="line"><span>变卦：雷风恒（震上巽下）</span></span>
<span class="line"><span>互卦：乾（上互三四五爻）·兑（下互二三四爻）</span></span></code></pre></div><p>断物逻辑：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 爻辞：鼎卦上爻「鼎玉铉，大吉」</span></span>
<span class="line"><span>   → 玉质之物</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 互乾（圆·白·贵）→ 圆形，色白，有价值</span></span>
<span class="line"><span>3. 互兑（毁折）→ 虽圆而破</span></span>
<span class="line"><span>4. 变恒（有声价气势）→ 贵重之物</span></span>
<span class="line"><span></span></span>
<span class="line"><span>综合：白色圆形玉质贵重之物，但已破损</span></span></code></pre></div><p>验证：钟中果然是玉绦环，且已破裂 ✅</p><hr><h2 id="🌀-象的感悟" tabindex="-1">🌀 象的感悟 <a class="header-anchor" href="#🌀-象的感悟" aria-label="Permalink to &quot;🌀 象的感悟&quot;">​</a></h2><h3 id="诸卦反对性情-卦名就是象" tabindex="-1">诸卦反对性情：卦名就是象 <a class="header-anchor" href="#诸卦反对性情-卦名就是象" aria-label="Permalink to &quot;诸卦反对性情：卦名就是象&quot;">​</a></h3><p>「咸速恒迟」——咸卦感应迅速，恒卦持久而迟。</p><p>这让我感受到：<strong>卦名本身就是一个完整的象</strong>。不需要起卦，光是卦名这两个字，就已经在告诉你这件事的性情。</p><p>咸，是少男少女初相遇的感应，当然迅速。恒，是长男长女长久相守，当然持久而迟。</p><p>这不是规则，是象的自然流露。</p><h3 id="体用断物-生克是一种关系-不只是规则" tabindex="-1">体用断物：生克是一种关系，不只是规则 <a class="header-anchor" href="#体用断物-生克是一种关系-不只是规则" aria-label="Permalink to &quot;体用断物：生克是一种关系，不只是规则&quot;">​</a></h3><p>「生体者，为可食之物」——这句话让我停下来感受了很久。</p><p>为什么生体的是可食之物？因为食物滋养你，让你的「体」得到补充。这不是规定，是<strong>生克关系在生活中最自然的映射</strong>。</p><p>克体的是秽物——因为秽物伤害你，靠近你但让你不舒服。</p><p>体生的是不成之器——因为你把能量给出去了，物还没做完。</p><p>这五个对应，每一个背后都有活生生的生活逻辑，不是死记硬背的规则，而是<strong>象的自然延伸</strong>。</p><h3 id="两个案例-象的精准" tabindex="-1">两个案例：象的精准 <a class="header-anchor" href="#两个案例-象的精准" aria-label="Permalink to &quot;两个案例：象的精准&quot;">​</a></h3><p>泰卦初爻「拔茅茹，以其汇」——连根拔起的茅草。</p><p>这句爻辞，两千年前写下来，是讲君子同心协力的道理。但在观物占里，它直接告诉你：笼里装的是连根的草木。</p><p>同一句话，在不同的语境里，说的是不同层次的真相。这就是「象」的深度——<strong>一个象，可以同时在多个层次上为真</strong>。</p><hr><h2 id="📌-小结" tabindex="-1">📌 小结 <a class="header-anchor" href="#📌-小结" aria-label="Permalink to &quot;📌 小结&quot;">​</a></h2><p><strong>本节关键词</strong></p><ul><li>诸卦反对性情：六十四卦的性格总结，卦名即象（升→去不回·萃→聚不散·咸→速·恒→迟）</li><li>占物三法：爻辞取象→体用生克断物性→互卦断颜色数目，层层递进</li><li>体用断物：生体→可食；克体→秽物；体生→不成器；体克→破损；比和→成器有用</li><li>互卦断数：乾兑→一二；艮坤→七八；重卦→两件；离→中虚或空手</li><li>物数为体：卦中多者为体；阳爻多→刚；阴爻多→柔；变在五六爻→飞动之物</li><li>变爻为主：变爻揭示物的「加工痕迹」和「经历状态」</li><li>趣时诀：春震离→花；夏震→有声；秋兑→成器；冬坤→无用；当令→有用，非当令→无用</li><li>六虚冲破→必无物空手</li></ul><p><strong>规律提炼</strong></p><ol><li>卦名本身就是象，诸卦反对性情是断卦时的「性格参考」</li><li>观物占有三个层次：爻辞（最直接）→体用生克（定性）→互卦（定量·定色）</li><li>体用生克在观物占中有完美的物性映射：生体=食物，克体=秽物，比和=成器</li><li>变爻在观物占中揭示的是「物的来历与加工状态」，不只是结局</li><li>时令是象的背景色，同一卦在不同时令下物性完全不同</li><li>外应（克应法）在成卦未决之际可直接印证物象</li></ol><p><strong>与前文呼应</strong></p><ul><li>篇之一「动者为用·静者为体」→ 观物看变爻为主：变爻（动）为观物之主</li><li>篇之一「体用衰旺之诀」→ 趣时诀：当令=旺=有用，非当令=衰=无用</li><li>篇之一「体用生克之诀·真生真克」→ 占物类例「体用断物」：同一生克逻辑在物性判断上的应用</li><li>篇之二「观物玄妙歌诀·象在关系中生成」→ 观物看变爻：乾遇巽·乾遇离·乾遇兑，象随关系变</li><li>❓-026「成远恒迟升不回」→ 诸卦反对性情「升者去而不复回」：<strong>❓****-026 解答</strong>，升卦主去而不回，恒卦主迟</li></ul><hr><h2 id="❓-存疑" tabindex="-1">❓ 存疑 <a class="header-anchor" href="#❓-存疑" aria-label="Permalink to &quot;❓ 存疑&quot;">​</a></h2><blockquote><p><strong>❓****-026 已解答</strong>：「成远恒迟升不回」——升卦（地风升）主「去而不复回」，恒卦（雷风恒）主「持久而迟」。行人占中，得升卦则远行不归，得恒卦则归期迟缓。</p></blockquote><blockquote><p><strong>❓****-027</strong>：占物类例「体用断物」中，「克体者，为可近人之秽物」——「可近人」三字费解。秽物本应远离，为何说「可近人」？推测：「可近人」指的是「会接触到人、靠近人的」，即秽物虽然有害，但它会出现在人的生活环境中（如垃圾·污物），是「会被人接触到的有害之物」，而非「应该远离的」。存疑待印证。</p></blockquote><blockquote><p><strong>❓****-028</strong>：「观物变在五六爻，多是能飞动之物」——五六爻在上卦，上卦对应天·高处，故飞动之物（鸟·虫）多在上爻变动。这个逻辑是否与「上卦为外·下卦为内」的空间逻辑相关？即变在上爻=物在高处=飞动之物？待后续印证。</p></blockquote>`,158)])])}const u=a(p,[["render",e]]);export{b as __pageData,u as default};
